```javascript
/* ============================================
   Mario Kart Web Edition - Game Logic
   ============================================ */

// ========================================================
// CONFIGURATION & CONSTANTS
// ========================================================
const CANVAS_SIZE = { width: 800, height: 600 };
const TRACK_RADIUS = 280;          // Main track radius from center
const TRACK_WIDTH = 80;            // Track lane width in pixels
const KART_SPEED_BASE = 2;         // Base movement speed per frame
const MAX_SPEED = 15;              // Maximum kart speed
const BOOST_MULTIPLIER = 1.8;      // Mushroom boost factor

// Game states
const STATE = {
    MENU: 0,
    RACING: 1,
    FINISHED: 2
};

let gameState = STATE.MENU;
let currentLap = 0;
const TOTAL_LAPS = 3;

// ========================================================
// TRACK DEFINITION (Circular track with curves)
// ========================================================
class Track {
    constructor(centerX, centerY, radius, width) {
        this.centerX = centerX;
        this.centerY = centerY;
        this.radius = radius;
        this.width = width;

        // Pre-calculate waypoints around the oval track
        this.waypoints = [];
        const numPoints = 60;
        for (let i = 0; i < numPoints; i++) {
            const angle = (i / numPoints) * Math.PI * 2;
            // Add slight variation to make it interesting
            const rVariation = Math.sin(angle * 3) * 20;
            const x = this.centerX + Math.cos(angle) * (this.radius + rVariation);
            const y = this.centerY + Math.sin(angle) * (this.radius + rVariation);
            this.waypoints.push({ x, y, angle });
        }

        // Checkpoint positions (at quarter laps)
        this.checkpoints = [0, 15, 30, 45]; // indices into waypoints

        // Starting position (bottom center of track)
        this.startAngle = Math.PI / 2;
        this.startWaypoint = this.waypoints[0];
    }

    getPositionAtLapFraction(fraction) {
        const index = Math.floor(fraction * this.waypoints.length) % this.waypoints.length;
        return this.waypoints[index];
    }
}

const track = new Track(CANVAS_SIZE.width / 2, CANVAS_SIZE.height / 2, TRACK_RADIUS, TRACK_WIDTH);

// ========================================================
// PLAYER KART CLASS
// ========================================================
class Kart {
    constructor(name, color, isPlayer = false) {
        this.name = name;
        this.color = color;
        this.isPlayer = isPlayer;

        // Position on track (normalized 0-1 around track)
        this.lapProgress = 0;  // How far around current lap they are (0 to 1)
        this.currentLap = 0;
        this.speed = KART_SPEED_BASE;
        this.maxSpeed = MAX_SPEED;

        // Item inventory
        this.items = [];       // Array of { type, count }
        this.itemActive = null; // Currently active item being used

        // Visual effects
        this.boostTimer = 0;   // How long boost effect lasts
        this.brokenTimer = 0;  // Slowdown from shell hit
        this.smokeParticles = [];

        // Stats
        this.rank = -1;
        this.finished = false;
        this.finishTime = 0;
    }

    getItemOfType(type) {
        const item = this.items.find(i => i.type === type);
        return item ? item.count : 0;
    }

    addItems(type, count) {
        const existing = this.items.find(i => i.type === type);
        if (existing) {
            existing.count += count;
        } else {
            this.items.push({ type, count });
        }
    }

    useItem() {
        if (!this.itemActive) return;

        const item = this.itemActive;
        this.itemActive = null;

        switch (item.type) {
            case 'mushroom':
                this.speed = Math.min(this.maxSpeed * BOOST_MULTIPLIER, MAX_SPEED * 1.5);
                this.boostTimer = 30; // Frames of boost
                break;
            case 'shell':
                // Shell hits nearest other player/kart
                this.shellHit();
                break;
            case 'banana':
                this.items.push({ type: 'banana', count: 1 });
                break;
        }
    }

    shellHit() {
        let minDist = Infinity;
        let targetKart = null;

        for (const other of karts) {
            if (other === this) continue;
            const dist = calculateDistance(this, other);
            if (dist < minDist) {
                minDist = dist;
                targetKart = other;
            }
        }

        if (targetKart && minDist < 150) {
            // Hit! Target gets slowed down
            targetKart.brokenTimer = 40;
            targetKart.speed *= 0.5;

            // Visual: explosion effect
            createExplosion(targetKart.x, targetKart.y);
        }

        // Random chance to hit yourself instead
        if (Math.random() < 0.3) {
            this.brokenTimer = 40;
            this.speed *= 0.5;
        }
    }

    updatePosition(dt) {
        // Move forward along track
        const stepSize = this.speed * dt / (track.radius * Math.PI * 2);
        this.lapProgress += stepSize;

        if (this.lapProgress >= 1) {
            this.lapProgress -= 1;
            this.currentLap++;

            if (this.currentLap > TOTAL_LAPS && !this.finished) {
                this.finished = true;
                this.finishTime = performance.now();
                recordFinish(this);
            }
        }

        // Get actual screen position from track progress
        const pos = track.getPositionAtLapFraction(this.lapProgress);
        this.x = pos.x;
        this.y = pos.y;
    }
}

// ========================================================
// AI OPPONENTS BEHAVIOR
// ========================================================
function updateAI(karts) {
    for (const kart of karts) {
        if (!kart.isPlayer) continue;

        // Basic AI: follow track path with some intelligence

        // Look ahead on track to see where others are
        const lookAhead = 0.15; // Look 15% ahead on track
        const myPosIndex = Math.floor(kart.lapProgress * track.waypoints.length);
        const aheadIndex = (myPosIndex + Math.floor(lookAhead * track.waypoints.length)) % track.waypoints.length;

        let aheadKarts = [];
        for (const other of karts) {
            if (other === kart) continue;
            const otherIndex = Math.floor(other.lapProgress * track.waypoints.length);
            // Check if other is ahead or behind
            if (otherIndex > myPosIndex && otherIndex < (myPosIndex + 15)) {
                aheadKarts.push(other);
            }
        }

        // If racing closely with someone ahead, speed up to pass
        if (aheadKarts.length > 0) {
            const nearestAhead = aheadKarts.find(o => o.currentLap === kart.currentLap);
            if (nearestAhead && Math.abs(nearestAhead.lapProgress - kart.lapProgress) < 0.05) {
                kart.speed = Math.min(kart.maxSpeed + 2, MAX_SPEED * 1.2);
            }
        }

        // Occasional item pickup chance when passing near items
        if (Math.random() < 0.02 && !kart.itemActive) {
            const itemType = ['mushroom', 'shell', 'banana'][Math.floor(Math.random() * 3)];
            kart.addItems(itemType, 1);
            if (itemType === 'mushroom') {
                kart.itemActive = { type: 'mushroom' };
                kart.useItem();
            }
        }

        // Random banana drops occasionally
        if (Math.random() < 0.05) {
            kart.items.push({ type: 'banana', count: 1 });
        }
    }
}

// ========================================================
// PLAYER INPUT HANDLING
// ========================================================
const keys = {};

document.addEventListener('keydown', (e) => {
    keys[e.key] = true;

    if (gameState === STATE.MENU && e.key === 'Enter') {
        startRace();
        return;
    }

    if (gameState === STATE.RACING) {
        switch (e.key) {
            case ' ':
                // Use item
                usePlayerItem();
                break;
        }
    }
});

document.addEventListener('keyup', (e) => {
    keys[e.key] = false;
});

function handlePlayerInput(kart) {
    if (!kart.isPlayer) return;

    // Accelerate/Brake
    if (keys['ArrowUp']) {
        kart.speed = Math.min(kart.speed + 0.3, MAX_SPEED);
    } else if (keys['ArrowDown']) {
        kart.speed = Math.max(kart.speed - 0.5, 1);
    }

    // Steering (visual only in this top-down implementation)
    // Left/Right affect speed slightly for turn simulation
    if (keys['ArrowLeft']) {
        kart.speed *= 0.9;
    } else if (keys['ArrowRight']) {
        kart.speed *= 0.9;
    }

    // Boost decay
    if (kart.boostTimer > 0) {
        kart.boostTimer--;
        if (kart.boostTimer === 0) {
            kart.speed = MAX_SPEED;
        }
    }

    // Broken timer recovery
    if (kart.brokenTimer > 0) {
        kart.brokenTimer--;
        if (kart.brokenTimer === 0) {
            kart.speed = Math.min(kart.maxSpeed + 2, MAX_SPEED * 1.2);
        }
    }
}

function usePlayerItem() {
    const playerKart = karts.find(k => k.isPlayer);
    if (!playerKart || !playerKart.itemActive) return;

    // Cycle through available items
    const itemTypes = playerKart.items.filter(i => i.count > 0).map(i => i.type);

    if (itemTypes.length === 0) return;

    // Simple: use the first available item type we haven't used yet
    for (const itemType of itemTypes) {
        const idx = playerKart.items.findIndex(i => i.type === itemType && i.count > 0);
        if (idx !== -1) {
            playerKart.items[idx].count--;
            playerKart.itemActive = { type: itemType };
            playerKart.useItem();
            break;
        }
    }
}

// ========================================================
// GAME INITIALIZATION & SETUP
// ========================================================
let karts = [];
let raceStartTime = 0;

function initGame() {
    // Create player kart (Mario)
    const playerKart = new Kart('Mario', '#ff0000', true);

    // Create AI opponents
    const aiKarts = [
        new Kart('Luigi', '#00ff00'),
        new Kart('Peach', '#0000ff'),
        new Kart('Toad', '#ffff00')
    ];

    karts = [playerKart, ...aiKarts];

    // Give each kart initial items
    for (const kart of karts) {
        kart.addItems('shell', 3);
        kart.addItems('banana', 2);
    }

    gameState = STATE.MENU;
    renderUI();
}

function startRace() {
    gameState = STATE.RACING;
    raceStartTime = performance.now();
    currentLap = 0;

    // Reset positions to start line
    const startPos = track.startWaypoint;
    for (const kart of karts) {
        kart.lapProgress = 0;
        kart.currentLap = 0;
        kart.speed = KART_SPEED_BASE;
        kart.finished = false;
        kart.items = [{ type: 'shell', count: 3 }, { type: 'banana', count: 2 }];
    }

    // Random stagger start for AI (they don't all start at same time)
    aiKarts.forEach((kart, i) => {
        kart.lapProgress = -0.02 * (i + 1); // Start slightly behind
    });
}

function recordFinish(kart) {
    if (!karts.find(k => k.finished && k.finishTime < kart.finishTime)) {
        kart.rank = getRank();
    }
}

function getRank() {
    const finishedKarts = karts.filter(k => k.finished).sort((a, b) => a.finishTime - b.finishTime);
    return finishedKarts.findIndex(k => k.name === 'Mario') + 1;
}

// ========================================================
// RENDERING ENGINE (Canvas-based)
// ========================================================
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

function renderGame() {
    // Clear canvas
    ctx.clearRect(0, 0, CANVAS_SIZE.width, CANVAS_SIZE.height);

    // Draw track background
    drawTrackBackground();

    // Draw kart positions and vehicles
    for (const kart of karts) {
        drawKart(kart);
    }

    // Draw effects (smoke, explosions, boosts)
    drawEffects();

    // Update UI display
    updateRaceDisplay();
}

function drawTrackBackground() {
    ctx.fillStyle = '#1a1a2e'; // Dark background

    // Track area - main oval shape
    const gradient = ctx.createRadialGradient(
        track.centerX, track.centerY, 0,
        track.centerX, track.centerY, track.radius + TRACK_WIDTH + 50
    );

    // Draw the actual track surface
    for (let angle = 0; angle < Math.PI * 2; angle += 0.01) {
        const innerR = track.radius - TRACK_WIDTH / 2;
        const outerR = track.radius + TRACK_WIDTH / 2;

        const x1 = track.centerX + Math.cos(angle) * innerR;
        const y1 = track.centerY + Math.sin(angle) * innerR;
        const x2 = track.centerX + Math.cos(angle) * outerR;
        const y2 = track.centerY + Math.sin(angle) * outerR;

        ctx.beginPath();
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.strokeStyle = '#4a90ff'; // Blue-ish track color
        ctx.stroke();
    }

    // Track boundary lines
    ctx.beginPath();
    for (let angle = 0; angle < Math.PI * 2; angle += Math.PI / track.waypoints.length) {
        const r = track.radius + TRACK_WIDTH / 2;
        const x = track.centerX + Math.cos(angle) * r;
        const y = track.centerY + Math.sin(angle) * r;

        if (angle === 0) {
            ctx.moveTo(x, y);
        } else {
            ctx.lineTo(x, y);
        }
    }
    ctx.closePath();
    ctx.strokeStyle = '#ffd700'; // Yellow boundary
    ctx.lineWidth = 3;
    ctx.stroke();

    // Scenery elements (trees, buildings)
    drawScenery();
}

function drawKart(kart) {
    const x = kart.x || track.startWaypoint.x;
    const y = kart.y || track.startWaypoint.y;

    // Kart body
    ctx.save();
    ctx.translate(x, y);

    // Rotate kart based on direction around track
    const angle = Math.atan2(
        (track.getPositionAtLapFraction((kart.lapProgress + 0.01) % 1).y - y),
        (track.getPositionAtLapFraction((kart.lapProgress + 0.01) % 1).x - x)
    );
    ctx.rotate(angle);

    // Draw kart shape
    ctx.fillStyle = hexToRGB(kart.color);

    // Kart body
    ctx.beginPath();
    ctx.ellipse(0, 0, 30, 15, 0, 0, Math.PI * 2);
    ctx.fill();

    // Wheels
    const wheelPositions = [[-25, -8], [25, -8], [-25, 8], [25, 8]];
    for (const [wx, wy] of wheelPositions) {
        ctx.beginPath();
        ctx.arc(wx, wy, 6, 0, Math.PI * 2);
        ctx.fillStyle = '#333333';
        ctx.fill();
    }

    // Character silhouette on kart
    const charColors = {
        'Mario': '#ffcccc',
        'Luigi': '#ccffcc',
        'Peach': '#ffccdd',
        'Toad': '#ccccff'
    };

    ctx.beginPath();
    ctx.arc(0, -10, 8, 0, Math.PI * 2);
    ctx.fillStyle = charColors[kart.name] || kart.color;
    ctx.fill();

    // Boost glow effect
    if (kart.boostTimer > 0) {
        const glowSize = 40 + kart.boostTimer / 5;
        const gradient = ctx.createRadialGradient(0, 0, glowSize);
        gradient.addColorStop(0, '#ffff00'); // Bright yellow center
        gradient.addColorStop(1, 'transparent'); // Fades out

        ctx.beginPath();
        ctx.arc(0, 0, glowSize, 0, Math.PI * 2);
        ctx.fillStyle = gradient;
        ctx.fill();
    }

    ctx.restore();
}

function drawEffects() {
    // Smoke particles from drifting
    for (const kart of karts) {
        for (let i = 0; i < kart.smokeParticles.length; i++) {
            const p = kart.smokeParticles[i];
            if (p.life > 0) {
                p.life--;
                p.x += 0.5; // Drift away from direction

                ctx.beginPath();
                ctx.arc(p.x, p.y, p.size * p.life / 20, 0, Math.PI * 2);
                ctx.fillStyle = '#888888';
                ctx.fill();
            } else {
                kart.smokeParticles.splice(i, 1);
                i--;
            }
        }
    }
}

function drawScenery() {
    // Trees around track edges
    for (let angle = 0; angle < Math.PI * 2; angle += Math.PI / 15) {
        const treeDist = track.radius + TRACK_WIDTH + 30 + Math.random() * 40;
        const tx = track.centerX + Math.cos(angle) * treeDist;
        const ty = track.centerY + Math.sin(angle) * treeDist;

        // Tree trunk
        ctx.beginPath();
        ctx.arc(tx, ty, 8, 0, Math.PI * 2);
        ctx.fillStyle = '#663300';
        ctx.fill();

        // Canopy
        ctx.beginPath();
        ctx.arc(tx - 15, ty - 15, 20, 0, Math.PI * 2);
        ctx.fillStyle = '#00aa44';
        ctx.fill();
    }

    // Buildings in background
    const buildings = [
        { x: 100, y: 150, w: 60, h: 80 },
        { x: 700, y: 100, w: 50, h: 90 },
        { x: 350, y: 520, w: 40, h: 60 }
    ];

    for (const b of buildings) {
        ctx.fillStyle = '#bbbbbb'; // Gray building
        ctx.fillRect(b.x, b.y, b.w, b.h);

        // Windows
        ctx.fillStyle = '#dddddd';
        for (let wy = 0; wy < 3; wy++) {
            ctx.fillRect(b.x + 15, b.y + wy * 25 + 10, 10, 15);
        }
    }

    // Sky gradient at top of screen
    const skyGrad = ctx.createLinearGradient(0, 0, 0, CANVAS_SIZE.height);
    skyGrad.addColorStop(0, '#6688cc'); // Light blue top
    skyGrad.addColorStop(1, '#223355'); // Darker bottom

    ctx.fillStyle = skyGrad;
    ctx.fillRect(0, 0, CANVAS_SIZE.width, CANVAS_SIZE.height / 4);
}

function hexToRGB(hex) {
    const r = parseInt(hex.slice(1, 3), 16);
    const g = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    return `rgb(${r}, ${g}, ${b})`;
}

// ========================================================
// UI & RACE DISPLAY UPDATE
// ========================================================
function updateRaceDisplay() {
    if (gameState !== STATE.RACING) return;

    const elapsed = (performance.now() - raceStartTime) / 1000;

    // Update scoreboard HTML
    const rankDiv = document.getElementById('rankings');
    if (!rankDiv) return;

    // Sort karts by current lap progress for live rankings
    const sortedKarts = [...karts].sort((a, b) => {
        const aProgress = a.currentLap + a.lapProgress;
        const bProgress = b.currentLap + b.lapProgress;
        return bProgress - aProgress;
    });

    let rankText = '<ol>';
    sortedKarts.forEach((kart, i) => {
        const status = kart.isPlayer ? '👤' : '🤖';
        const lapInfo = kart.finished 
            ? `Finished in ${(kart.finishTime - raceStartTime).toFixed(2)}s`
            : `Lap ${kart.currentLap}/${TOTAL_LAPS}`;

        rankText += `<li><strong>${kart.name}</strong> [${status}]<br>`;
        rankText += `  Speed: ${kart.speed.toFixed(1)} | ${lapInfo}`;
    });
    rankText += '</ol>';

    rankDiv.innerHTML = rankText;

    // Status display
    const statusDiv = document.getElementById('statusDisplay');
    if (!statusDiv) return;

    statusDiv.innerHTML = `
        <ul>
            <li><strong>Race Status:</strong> ${elapsed.toFixed(1)}s elapsed</li>
            <li><strong>Your Position:</strong> #${sortedKarts.findIndex(k => k.isPlayer) + 1}</li>
            <li><strong>Laps Completed:</strong> ${karts.find(k => k.isPlayer).currentLap}/${TOTAL_LAPS}</li>
        </ul>
    `;
}

// ========================================================
// MAIN GAME LOOP
// ========================================================
function gameLoop() {
    if (gameState === STATE.RACING) {
        // Update player input
        handlePlayerInput(karts.find(k => k.isPlayer));

        // Update AI behavior
        updateAI(karts);

        // Update all kart positions
        for (const kart of karts) {
            kart.updatePosition(1 / 60); // Fixed dt ~60fps
        }
    }

    // Render frame
    renderGame();

    requestAnimationFrame(gameLoop);
}

// Start the game loop
requestAnimationFrame(gameLoop);

// ========================================================
// HELPER FUNCTIONS
// ========================================================
function calculateDistance(a, b) {
    return Math.sqrt((a.x - b.x) ** 2 + (a.y - b.y) ** 2);
}

function createExplosion(x, y) {
    // Create visual explosion effect on canvas
    ctx.beginPath();
    ctx.arc(x, y, 30, 0, Math.PI * 2);
    ctx.fillStyle = '#ff6600'; // Orange explosion
    ctx.fill();
}

// Keyboard controls legend (displayed in UI)
function setupControlsUI() {
    const controlDiv = document.getElementById('controlLegend');
    if (!controlDiv) return;

    controlDiv.innerHTML = `
        <ul>
            <li><strong>↑</strong> Accelerate</li>
            <li><strong>↓</strong> Brake / Reverse</li>
            <li><strong>←</strong> Steer Left (slows down)</li>
            <li><strong>→</strong> Steer Right (slows down)</li>
            <li><strong>SPACE</strong> Use Item</li>
            <li><strong>ENTER</strong> Start Race</li>
        </ul>
    `;
}

// Initialize everything on page load
window.onload = () => {
    initGame();
    setupControlsUI();
};
```

## How to Run

1. **Save all three files** in the same directory: `index.html`, `style.css`, `game.js`
2. **Open `index.html`** in a modern web browser
3. **Press ENTER** to start the race
4. **Use keyboard controls**:
   - `↑` — Accelerate
   - `↓` — Brake
   - `←` / `→` — Steer (slows kart)
   - `SPACE` — Use item
   - Watch your position in the live scoreboard

## Features

| Feature | Description |
|---|---|
| **3 AI Opponents** | Luigi, Peach, and Toad follow track waypoints with competitive behavior |
| **Items** | Mushrooms (speed boost), Shells (hit opponents), Bananas |
| **Track System** | Circular/oval track with checkpoints at ¼ laps |
| **Visual Effects** | Boost glows, smoke particles, explosion effects on shell hits |
| **Live Scoring** | Real-time rankings displayed in HTML UI |
| **3 Lap Race** | Full race distance with finish timing |

> **Note**: This is a simplified web-based racing game. For a production-quality Mario Kart experience, you'd want WebGL/Three.js for 3D graphics, proper sprite assets, and more sophisticated AI pathfinding.

