## 🕹️ `game.js`

```javascript
/**
 * Mario Kart Web Edition
 * A complete browser-based racing game
 */

const canvas = document.getElementById('race-canvas');
const ctx = canvas.getContext('2d');

// ========== GAME CONFIGURATION ==========
const CONFIG = {
  TRACK_WIDTH: 10,          // Track width in grid units
  NUM_LAPS: 3,
  MAX_SPEED: 8,             // Max movement speed per frame
  ACCEL_POWER: 0.15,        // Acceleration power
  BRAKE_FORCE: 0.08,        // Braking deceleration
  TRACK_RADIUS: 200,        // Main oval radius
  KART_SIZE: 30,            // Kart sprite dimensions
  ITEMS_PER_PLAYER: {
    banana: 3,
    shell: 2,
    mushroom: 1,
  }
};

// ========== GAME STATE ==========
const gameState = {
  running: false,
  startedAt: null,
  currentTime: 0,
  currentLap: 0,
  players: [],
  particles: [],       // Environmental particle effects
  itemsOnTrack: [],    // Items dropped on track (bananas/shells)
  mushroomEffects: {}, // Active mushroom speed boosts
};

// ========== TRACK GENERATION ==========
function generateTrack() {
  const points = [];
  const segments = 60; // Resolution of track curve

  for (let i = 0; i < segments; i++) {
    const angle = (i / segments) * Math.PI * 2;

    // Main oval track with varying radius sections
    let r = CONFIG.TRACK_RADIUS + Math.sin(angle * 3) * 50;

    const x = Math.cos(angle) * r;
    const y = Math.sin(angle) * r;

    points.push({ x, y, angle });
  }

  // Add inner and outer track boundaries
  const innerPoints = [];
  const outerPoints = [];

  for (let i = 0; i < segments; i++) {
    const p = points[i];
    const nextP = points[(i + 1) % segments];

    const dirX = nextP.x - p.x;
    const dirY = nextP.y - p.y;
    const dist = Math.sqrt(dirX * dirX + dirY * dirY);

    // Perpendicular offset
    const perpX = -dirY / dist;
    const perpY = dirX / dist;

    innerPoints.push({
      x: p.x + perpX * (CONFIG.TRACK_WIDTH * 30),
      y: p.y + perpY * (CONFIG.TRACK_WIDTH * 30)
    });

    outerPoints.push({
      x: p.x - perpX * (CONFIG.TRACK_WIDTH * 30),
      y: p.y - perpP * (CONFIG.TRACK_WIDTH * 30)
    });
  }

  return { points, innerPoints, outerPoints, segments };
}

// ========== PLAYER CLASS ==========
class Player {
  constructor(name, kartColor, startPosIndex, ai = false) {
    this.name = name;
    this.kartColor = kartColor;   // String like 'red', 'blue', etc.
    this.posIndex = startPosIndex;  // Current position on track
    this.speed = 0;               // Current velocity
    this.ai = ai;                 // Whether it's AI controlled
    this.items = { ...CONFIG.ITEMS_PER_PLAYER };
    this.boostActive = false;     // Mushroom boost flag
    this.injured = false;         // Hit by shell
    this.lastPosition = null;
    this.positionHistory = [];    // For lap tracking
    this.lapTimes = [];           // Times per lap
  }

  getPosition() {
    const track = gameState.track;
    const segIdx = Math.floor(this.posIndex % track.points.length);
    const p1 = track.points[segIdx];
    const p2 = track.points[(segIdx + 1) % track.points.length];

    const t = this.posIndex % 1; // Fraction along segment
    return {
      x: p1.x + (p2.x - p1.x) * t,
      y: p1.y + (p2.y - p1.y) * t
    };
  }

  distanceBetween(p1, p2) {
    return Math.sqrt((p1.x - p2.x)**2 + (p1.y - p2.y)**2);
  }
}

// ========== INPUT HANDLING ==========
const keys = new Map();

function handleKeyDown(e) {
  keys.set(e.key, true);

  if (e.key === ' ' || e.key === 'Enter') {
    startRace();
  }

  // Item throwing
  if ((e.key === 'e' || e.key === 'r') && gameState.running) {
    const player = getCurrentPlayer();
    if (player.items.banana > 0) {
      player.items.banana--;
      throwItem(player, 'banana');
    }
  }

  // Mushroom boost
  if (e.key === 'c' && gameState.running) {
    const player = getCurrentPlayer();
    if (player.items.mushroom > 0) {
      player.items.mushroom--;
      activateMushroom(player);
    }
  }
}

function handleKeyUp(e) {
  keys.set(e.key, false);
}

function getCurrentPlayer() {
  // For single-player mode
  return gameState.players[0];
}

// ========== RACE START/STOP ==========
function startRace() {
  if (gameState.running) return;

  gameState.running = true;
  gameState.startedAt = Date.now();
  gameState.currentLap = 1;

  // Create players
  createPlayers();

  updateHUD();
  requestAnimationFrame(gameLoop);
}

function stopRace() {
  gameState.running = false;
}

// ========== PLAYER CREATION ==========
function createPlayers() {
  const playerConfigs = [
    { name: 'Mario', color: '#ff0000' },      // Red kart
    { name: 'Luigi', color: '#0044ff' },      // Blue kart  
    { name: 'Peach', color: '#ffff00' },      // Yellow kart
    { name: 'Bowser', color: '#00aa00' },     // Green kart
  ];

  gameState.players = playerConfigs.map((cfg, i) => 
    new Player(cfg.name, cfg.color, i * 4, false)
  );
}

// ========== AI OPPONENTS ==========
function updateAI(opponent) {
  if (!opponent.ai) return;

  // Simple AI: follow the player with variation
  const currentPos = getCurrentPlayer();
  const aiPos = getPosition(opponent);
  const aiCurrentIdx = opponent.posIndex;

  // Try to stay ahead of or behind the player
  const diff = aiCurrentIdx - currentPos.posIndex;

  let targetSpeed = CONFIG.MAX_SPEED * (0.6 + Math.random() * 0.3);

  if (diff > 0) {
    // AI is ahead, maintain speed
    opponent.speed = targetSpeed;
  } else {
    // AI behind, try to catch up
    opponent.speed = targetSpeed * 1.2;

    // Occasionally drop items to slow player
    if (Math.random() < 0.05 && opponent.items.banana > 0) {
      throwItem(opponent, 'banana');
    }
  }

  // Slight steering toward center of track
  const playerPos = getPosition(currentPlayer);
  const angleDiff = Math.atan2(playerPos.y - aiPos.y, playerPos.x - aiPos.x);

  opponent.posIndex += (opponent.speed * Math.cos(angleDiff));
}

// ========== ITEM THROWING ==========
function throwItem(player, itemType) {
  const pos = getPosition(player);

  gameState.itemsOnTrack.push({
    type: itemType,
    x: pos.x + Math.random() * 20 - 10, // Slight random offset
    y: pos.y + Math.random() * 20 - 10,
    lifetime: 30,       // How long it stays on track (frames)
    active: true
  });
}

function activateMushroom(player) {
  player.boostActive = true;
  gameState.mushroomEffects[player.name] = {
    activatedAt: Date.now(),
    duration: 60,        // Frames of boost
    originalSpeed: player.speed
  };

  player.speed = CONFIG.MAX_SPEED * 1.5; // Massive speed boost!
}

// ========== PHYSICS & COLLISION ==========
function checkCollisions() {
  for (let i = 0; i < gameState.players.length; i++) {
    const p = gameState.players[i];
    const pos = getPosition(p);

    // Check against items on track
    for (const item of gameState.itemsOnTrack) {
      if (!item.active) continue;

      const dist = distanceBetween(pos, { x: item.x, y: item.y });

      if (dist < 20) { // Collision radius
        if (item.type === 'banana') {
          p.injured = true;
          p.speed *= 0.3; // Slow down significantly
          item.active = false;

          // Add smoke effect
          gameState.particles.push({
            x: pos.x,
            y: pos.y,
            type: 'smoke',
            lifetime: 20,
            size: 30
          });
        } else if (item.type === 'shell') {
          p.injured = true;
          p.speed = 0;
          p.posIndex -= Math.random() * 10; // Knock backwards
          item.active = false;
        }
      }
    }

    // Check against other players (collision)
    for (let j = i + 1; j < gameState.players.length; j++) {
      const otherPos = getPosition(gameState.players[j]);
      const dist = distanceBetween(pos, otherPos);

      if (dist < CONFIG.KART_SIZE) {
        // Minor bump - both slow down slightly
        p.speed *= 0.9;
        gameState.players[j].speed *= 0.9;

        gameState.particles.push({
          x: (pos.x + otherPos.x) / 2,
          y: (pos.y + otherPos.y) / 2,
          type: 'spark',
          lifetime: 5,
          size: 15
        });
      }
    }
  }
}

// ========== LAP TRACKING ==========
function updateLapProgress() {
  for (const player of gameState.players) {
    const prevIndex = player.lastPosition;
    if (!prevIndex) {
      player.lastPosition = player.posIndex;
      continue;
    }

    // Check if crossed finish line
    const trackLen = gameState.track.points.length;
    if (player.posIndex > prevIndex && 
        player.posIndex - prevIndex > trackLen * 0.8) {

      player.lapTimes.push(Date.now() - gameState.startedAt);
      player.positionHistory.push({...});

      if (player.lapTimes.length >= CONFIG.NUM_LAPS) {
        // Race complete!
        gameState.running = false;
        showFinalResults(player.name, player.lapTimes);
      }
    }

    player.lastPosition = player.posIndex;
  }
}

// ========== GAME LOOP ==========
function gameLoop() {
  if (!gameState.running) return;

  // Update current time
  gameState.currentTime += 1;

  const currentPlayer = getCurrentPlayer();

  // Handle player input
  handleInput(currentPlayer);

  // Update AI opponents
  for (let i = 1; i < gameState.players.length; i++) {
    updateAI(gameState.players[i]);
  }

  // Apply physics to all players
  for (const player of gameState.players) {
    applyPhysics(player);

    // Check mushroom boost expiration
    const mushroomEffect = gameState.mushroomEffects[player.name];
    if (mushroomEffect && gameState.currentTime - mushroomEffect.activatedAt > mushroomEffect.duration) {
      player.speed = CONFIG.MAX_SPEED;
      player.boostActive = false;
      delete gameState.mushroomEffects[player.name];
    }
  }

  // Update items on track
  updateTrackItems();

  // Check collisions
  checkCollisions();

  // Update lap tracking
  updateLapProgress();

  // Update particles
  updateParticles();

  // Render everything
  render();

  requestAnimationFrame(gameLoop);
}

function handleInput(player) {
  if (!keys.has('ArrowUp')) {
    // Natural deceleration when no input
    player.speed *= (1 - CONFIG.ACCEL_POWER * 0.5);
    return;
  }

  const currentSpeed = player.speed;
  player.speed += CONFIG.ACCEL_POWER;
  player.speed = Math.min(player.speed, CONFIG.MAX_SPEED);

  // Steering left/right adjustments
  if (keys.has('ArrowLeft')) {
    player.posIndex -= 2; // Slight turn effect
  }
  if (keys.has('ArrowRight')) {
    player.posIndex += 2;
  }
}

function applyPhysics(player) {
  // Move forward along track
  const moveAmt = player.speed * CONFIG.ACCEL_POWER * 1.5;

  if (player.injured) {
    player.speed *= 0.98; // Gradually recover
    if (player.speed > 2) {
      player.injured = false;
    }
  }

  player.posIndex += moveAmt;

  // Loop around track
  if (player.posIndex > gameState.track.points.length * 10) {
    player.posIndex -= gameState.track.points.length * 10;
  }
}

function updateTrackItems() {
  for (const item of gameState.itemsOnTrack) {
    if (!item.active) continue;

    item.lifetime--;
    if (item.lifetime <= 0) {
      item.active = false;
    }
  }

  // Remove inactive items
  gameState.itemsOnTrack = gameState.itemsOnTrack.filter(i => i.active);
}

function updateParticles() {
  for (let i = 0; i < gameState.particles.length; i++) {
    const p = gameState.particles[i];
    p.lifetime--;

    if (p.type === 'smoke') {
      p.size += 2; // Smoke expands
    }
  }

  gameState.particles = gameState.particles.filter(p => p.lifetime > 0);
}

// ========== RENDERING ==========
function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Camera perspective - center on player
  const playerPos = getPosition(getCurrentPlayer());
  const centerX = canvas.width / 2;
  const centerY = canvas.height / 2;

  // Track rendering
  renderTrack();

  // Player karts rendering
  renderKarts();

  // Item effects rendering
  renderItemsOnTrack();

  // Particle effects rendering
  renderParticles();

  // Sky/weather background
  renderBackground();
}

function renderTrack() {
  const track = gameState.track;
  const center = { x: canvas.width / 2, y: canvas.height / 2 };

  // Draw main track path
  ctx.beginPath();
  for (let i = 0; i < track.points.length; i++) {
    const p = track.points[i];

    // Apply zoom and offset
    const sx = center.x + (p.x - center.x) * 1.2;
    const sy = center.y + (p.y - center.y) * 1.2;

    ctx.lineTo(sx, sy);
  }
  ctx.closePath();
  ctx.strokeStyle = '#444';
  ctx.stroke();

  // Draw grass/curbs
  for (let i = 0; i < track.innerPoints.length; i++) {
    const p = track.innerPoints[i];
    ctx.beginPath();
    ctx.arc(
      center.x + (p.x - center.x) * 1.2,
      center.y + (p.y - center.y) * 1.2,
      8, 0, Math.PI * 2
    );
    ctx.fillStyle = '#00aa44';
    ctx.fill();
  }
}

function renderKarts() {
  const center = { x: canvas.width / 2, y: canvas.height / 2 };

  for (const player of gameState.players) {
    const pos = getPosition(player);

    const sx = center.x + (pos.x - center.x) * 1.2;
    const sy = center.y + (pos.y - center.y) * 1.2;

    // Kart body
    ctx.beginPath();
    ctx.ellipse(sx, sy, CONFIG.KART_SIZE / 2, CONFIG.KART_SIZE / 3, player.angle || 0);
    ctx.fillStyle = player.kartColor;
    ctx.fill();

    // Mario character on kart
    ctx.fillStyle = '#ff0000';
    ctx.beginPath();
    ctx.arc(sx + 5, sy - 10, 8, 0, Math.PI * 2);
    ctx.fill();

    // Wheels (4 wheels)
    const wheelPositions = [
      { dx: -15, dy: -10 },
      { dx: 15, dy: -10 },
      { dx: -15, dy: 10 },
      { dx: 15, dy: 10 }
    ];

    for (const wp of wheelPositions) {
      ctx.fillStyle = '#222';
      ctx.beginPath();
      ctx.arc(
        sx + wp.dx * 1.2, 
        sy + wp.dy * 1.2, 
        5, 0, Math.PI * 2
      );
      ctx.fill();
    }

    // Boost effect visualization
    if (player.boostActive) {
      ctx.fillStyle = '#ff00ff';
      ctx.beginPath();
      ctx.arc(sx + 15, sy, 10, 0, Math.PI * 2);
      ctx.fill();

      // Speed lines behind kart
      for (let i = 0; i < 3; i++) {
        ctx.strokeStyle = '#ffff00';
        ctx.beginPath();
        ctx.moveTo(sx - 10 - i * 5, sy);
        ctx.lineTo(sx + 5 - i * 5, sy);
        ctx.stroke();
      }
    }

    // Injured effect (stars/eyes)
    if (player.injured) {
      ctx.fillStyle = '#ffff00';
      ctx.beginPath();
      for (let s = 0; s < 3; s++) {
        const angle = (s / 3) * Math.PI * 2 + Date.now() / 1000;
        ctx.moveTo(
          sx + 5 + Math.cos(angle) * 12,
          sy - 15 + Math.sin(angle) * 12
        );
        ctx.lineTo(sx + 5 + Math.cos(angle) * 8, sy - 15 + Math.sin(angle) * 8);
      }
      ctx.stroke();
    }

    // Smoke trail for injured karts
    if (player.injured && player.speed < 3) {
      ctx.fillStyle = '#888';
      ctx.beginPath();
      ctx.arc(sx, sy + 20, 15, 0, Math.PI * 2);
      ctx.fill();
    }
  }
}

function renderItemsOnTrack() {
  const center = { x: canvas.width / 2, y: canvas.height / 2 };

  for (const item of gameState.itemsOnTrack) {
    const sx = center.x + (item.x - center.x) * 1.2;
    const sy = center.y + (item.y - center.y) * 1.2;

    if (item.type === 'banana') {
      ctx.fillStyle = '#ff8800';
      ctx.beginPath();
      ctx.arc(sx, sy, 6, 0, Math.PI * 2);
      ctx.fill();

      // Warning sign effect
      ctx.strokeStyle = '#ffaa00';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(sx - 5, sy);
      ctx.lineTo(sx + 5, sy);
      ctx.stroke();
    } else if (item.type === 'shell') {
      ctx.fillStyle = '#4488ff';
      ctx.beginPath();
      ctx.arc(sx, sy, 10, 0, Math.PI * 2);
      ctx.fill();

      // Warning effect
      const pulse = Math.sin(Date.now() / 50) * 5;
      ctx.strokeStyle = '#ff0000';
      ctx.beginPath();
      ctx.moveTo(sx - 8 - pulse, sy);
      ctx.lineTo(sx + 8 + pulse, sy);
      ctx.stroke();
    }
  }
}

function renderParticles() {
  const center = { x: canvas.width / 2, y: canvas.height / 2 };

  for (const p of gameState.particles) {
    const sx = center.x + (p.x - center.x) * 1.2;
    const sy = center.y + (p.y - center.y) * 1.2;

    if (p.type === 'smoke') {
      ctx.fillStyle = `rgba(80,80,80,${p.lifetime/20})`;
      ctx.beginPath();
      ctx.arc(sx, sy, p.size, 0, Math.PI * 2);
      ctx.fill();
    } else if (p.type === 'spark') {
      ctx.fillStyle = '#ffff44';
      ctx.beginPath();
      ctx.arc(sx, sy, p.lifetime, 0, Math.PI * 2);
      ctx.fill();
    }
  }
}

function renderBackground() {
  // Simple sky gradient background
  for (let y = 0; y < canvas.height; y += 5) {
    const intensity = y / canvas.height;
    const color = `rgba(${120 + intensity * 130}, ${180 - intensity * 60}, ${255 - intensity * 100}, 0.3)`;
    ctx.fillStyle = color;

    for (let x = 0; x < canvas.width; x += 10) {
      ctx.fillRect(x, y, 10, 5);
    }
  }

  // Clouds and atmosphere
  const clouds = [
    { x: 150, y: 50, size: 40 },
    { x: 400, y: 30, size: 60 },
    { x: 700, y: 80, size: 30 }
  ];

  for (const c of clouds) {
    ctx.fillStyle = '#ddd';
    ctx.beginPath();
    ctx.arc(c.x, c.y, c.size, 0, Math.PI * 2);
    ctx.fill();

    // Cloud shadow underneath
    ctx.fillStyle = '#ccc';
    ctx.beginPath();
    ctx.arc(c.x + 15, c.y + 15, c.size * 0.7, 0, Math.PI * 2);
    ctx.fill();
  }
}

// ========== HUD & UI UPDATES ==========
function updateHUD() {
  const player = getCurrentPlayer();

  // Position calculation - rank by lap progress
  const sortedPlayers = [...gameState.players].sort((a, b) => {
    return a.posIndex - b.posIndex;
  });

  const position = sortedPlayers.findIndex(p => p === player) + 1;

  // Speed display
  const speedKmh = (player.speed * CONFIG.MAX_SPEED / 8 * 300).toFixed(0);

  // Lap tracking
  const lapsCompleted = gameState.lapTimes.length;

  document.querySelector('#hud .position-display').textContent = 
    `Position: ${position}`;
  document.querySelector('#hud .speed-display').textContent = 
    `Speed: ${speedKmh} km/h`;
  document.querySelector('#hud .lap-display').textContent = 
    `Lap: ${lapsCompleted} / ${CONFIG.NUM_LAPS}`;

  const itemCount = player.items.banana + player.items.shell + player.items.mushroom;
  document.querySelector('#hud .item-display').textContent = 
    `Items: Banana ×${player.items.banana}, Shell ×${player.items.shell}, Mushroom ×${player.items.mushroom}`;

  const raceStatusEl = document.querySelector('#race-status');
  if (!gameState.running) {
    raceStatusEl.textContent = '⏳ READY — Press Space or click Start';
  } else {
    raceStatusEl.textContent = `🏁 LAPING... Position #${position} | Speed: ${speedKmh} km/h`;
  }
}

function showFinalResults(playerName, lapTimes) {
  const totalTime = lapTimes.reduce((a, b) => a + b, 0);
  const avgLap = (totalTime / lapTimes.length).toFixed(0);

  ctx.fillStyle = '#ff4444';
  ctx.font = '36px bold-text';
  ctx.fillText(`🏁 ${playerName} FINISHES! 🏁`, canvas.width / 2, canvas.height / 2);

  setTimeout(() => {
    alert(`${playerName} completed the race in ${(totalTime/1000).toFixed(2)}s!\nAverage lap: ${(avgLap/1000).toFixed(2)}s`);

    // Reset game state
    resetGameState();
  }, 500);
}

function resetGameState() {
  gameState.players = [];
  gameState.particles = [];
  gameState.itemsOnTrack = [];
  gameState.running = false;
  gameState.currentTime = 0;

  updateHUD();

  // Clear canvas
  ctx.clearRect(0, 0, canvas.width, canvas.height);
}

// ========== INITIALIZATION ==========
function init() {
  // Setup game loop interval
  setInterval(() => {
    if (!gameState.running) return;

    requestAnimationFrame(gameLoop);
  }, 1000 / 60);

  // Create initial track
  gameState.track = generateTrack();

  // Set up event listeners
  window.addEventListener('keydown', handleKeyDown);
  window.addEventListener('keyup', handleKeyUp);

  // Auto-create players on load
  createPlayers();

  // Start the race automatically for demo purposes
  setTimeout(() => {
    startRace();
  }, 2000);
}

// ========== EVENT LISTENERS SETUP ==========
document.addEventListener('DOMContentLoaded', () => {
  init();
});
```

