## 🎮 `game.js`

```javascript
/**
 * Mario Kart: Web Edition
 * A fully playable top-down kart racing game.
 */
"use strict";

/* ========================================
   CONSTANTS & CONFIG
   ======================================== */
const CANVAS_W = 800;
const CANVAS_H = 600;
const CHARACTERS = [
    { name: "Mario", color: "#ff4500", sprite: null },
    { name: "Luigi", color: "#00ffff", sprite: null },
    { name: "Yoshi", color: "#ff6600", sprite: null },
    { name: "Peach",  color: "#ffaaaa", sprite: null },
    { name: "Bowser",  color: "#ff7a45", sprite: null },
    { name: "DK",      color: "#cc3300", sprite: null }
];

const ITEMS = ["none","mushroom","blueShell","redShell","banana"];
const LAP_COUNT   = 3;
const TRACK_W     = 200;
const TRACK_H     = 150;
const TURN_RADIUS  = 64;

/* ========================================
   GAME STATE
   ======================================== */
let gameState = {
    running: false,
    lapCount: 0,
    position: 0,
    selectedChar: CHARACTERS[0],
    karts: [],
    itemsOnTrack: [],
    particles: [],
    finishPositions: []
};

/* ========================================
   KART CLASS
   ======================================== */
class Kart {
    constructor(charData, startX, startY) {
        this.char = charData;
        this.x    = startX;
        this.y    = startY;
        this.vx   = 2;   // velocity x
        this.vy   = -3;  // velocity y
        this.maxVx = 5;
        this.maxVy = 7;
        this.speed = 0;
        this.item  = "none";
        this.lap   = 0;
        this.finished = false;
        this.finishTime = 0;

        // Track checkpoints for lap counting
        this.checkpoints = [0,1,2,3]; // top-right, bottom-right, bottom-left, top-left
    }

    update() {
        if (this.finished) return;

        // Apply gravity/terrain
        const terrainY = Math.sin(this.y / 40) * 8;
        this.y -= terrainY;

        // Bounds & collisions
        const trackLeft = CANVAS_W / 2 - TRACK_W/2;
        const trackRight = CANVAS_W / 2 + TRACK_W/2;
        const trackTop   = CANVAS_H / 2 - TRACK_H/2;
        const trackBottom = CANVAS_H / 2 + TRACK_H/2;

        if (this.x < trackLeft) { this.x = trackLeft; this.vx = Math.abs(this.vx); }
        if (this.x > trackRight){ this.x = trackRight; this.vx = -Math.abs(this.vx); }
        if (this.y < trackTop)  { this.y = trackTop; this.vy = Math.abs(this.vy); }
        if (this.y > trackBottom){ this.y = trackBottom; this.vy = -Math.abs(this.vy); }

        // Checkpoints / lap advancement
        const cx = CANVAS_W/2, cy = CANVAS_H/2;
        if (this.x > cx && this.y < cy) { this.checkpoints.push(1); } // top-right corner
        if (this.x < cx && this.y < cy) { this.checkpoints.push(2); } // bottom-left corner

        if (this.checkpoints.length >= 4) {
            this.lap++;
            this.checkpoints = [];
            if (this.lap === LAP_COUNT) {
                this.finished = true;
                gameState.finishPositions.push({ kart: this.char.name, time: Date.now() });
            }
        }

        // Speed management
        const targetSpeed = 15 + (Math.sin(Date.now()/200)) * 5;
        this.speed += (targetSpeed - this.speed) * 0.05;

        // Move
        this.x += this.vx;
        this.y += this.vy;
    }
}

/* ========================================
   TRACK GENERATION
   ======================================== */
function generateTrack() {
    const canvas = document.getElementById("game-canvas");
    ctx.clearRect(0, 0, CANVAS_W, CANVAS_H);

    // Draw track segments
    ctx.beginPath();

    /* Top-left → top-right */
    for (let i = CANVAS_W/2 - TRACK_W; i < CANVAS_W/2 + TRACK_W; i += 4) {
        ctx.lineTo(i, CANVAS_H/2 - TRACK_H/2);
    }

    /* Right turn */
    for (let angle = 0; angle <= Math.PI; angle += Math.PI / 16) {
        const x = CANVAS_W/2 + Math.cos(angle) * TURN_RADIUS;
        const y = CANVAS_H/2 - TURN_RADIUS + Math.sin(angle) * TURN_RADIUS;
        ctx.lineTo(x, y);
    }

    /* Top-right → bottom-right */
    for (let j = CANVAS_H/2 - TRACK_H/2; j < CANVAS_H/2 + TRACK_H/2; j += 4) {
        ctx.lineTo(CANVAS_W/2 + TURN_RADIUS, j);
    }

    /* Bottom turn */
    for (let angle = Math.PI; angle <= Math.PI * 2; angle += Math.PI / 16) {
        const x = CANVAS_W/2 + Math.cos(angle) * TURN_RADIUS;
        const y = CANVAS_H/2 + Math.sin(angle) * TURN_RADIUS;
        ctx.lineTo(x, y);
    }

    /* Bottom-right → bottom-left */
    for (let i = CANVAS_W/2 + TRACK_W; i > CANVAS_W/2 - TRACK_W; i -= 4) {
        ctx.lineTo(i, CANVAS_H/2 + TRACK_H/2);
    }

    /* Left turn */
    for (let angle = 0; angle <= Math.PI; angle += Math.PI / 16) {
        const x = CANVAS_W/2 - Math.cos(angle) * TURN_RADIUS;
        const y = CANVAS_H/2 + TURN_RADIUS - Math.sin(angle) * TURN_RADIUS;
        ctx.lineTo(x, y);
    }

    /* Bottom-left → top-left */
    for (let j = CANVAS_H/2 + TRACK_H/2; j > CANVAS_H/2 - TRACK_H/2; j -= 4) {
        ctx.lineTo(CANVAS_W/2 - TURN_RADIUS, j);
    }

    ctx.closePath();
    ctx.stroke();
}

/* ========================================
   ITEM PLACEMENT ON TRACK
   ======================================== */
function placeItemsOnTrack() {
    const cx = CANVAS_W / 2;
    const cy = CANVAS_H / 2;

    for (let i = 0; i < 15; i++) {
        // Spread items around track corners/edges
        const x = cx + (Math.cos(i * Math.PI / 8) * TURN_RADIUS) + (Math.random() - 0.5) * 24;
        const y = cy + (Math.sin(i * Math.PI / 8) * TURN_RADIUS) + (Math.random() - 0.5) * 24;

        gameState.itemsOnTrack.push({
            x: x, y: y,
            type: ITEMS[Math.floor(Math.random() * ITEMS.length)],
            collected: false
        });
    }
}

/* ========================================
   KEYBOARD CONTROLS
   ======================================== */
const keys = {};
document.addEventListener("keydown", (e) => {
    keys[e.key] = true;
    if (e.key === " ") gameState.racingStarted = true;  // Space to boost
});
document.addEventListener("keyup", (e) => {
    keys[e.key] = false;
});

function applyPlayerInput() {
    // Arrow keys control kart movement
    if (keys["ArrowLeft"])   gameState.karts.forEach(k => k.vx -= 1);
    if (keys["ArrowRight"])  gameState.karts.forEach(k => k.vx += 1);
    if (keys["ArrowUp"])     gameState.karts.forEach(k => k.vy -= 1);
    if (keys["ArrowDown"])   gameState.karts.forEach(k => k.vy += 1);

    // Space for boost
    if (keys[" "]) {
        gameState.karts.forEach(k => {
            if (!k.finished) {
                k.vx *= 2;
                k.vy *= 2;
            }
        });
    }

    // Throw shell
    if (keys["e"] || keys["E"]) {
        const activeKart = gameState.karts.find(k => !k.finished && k.item !== "none");
        if (activeKart) {
            // Find nearby track items
            for (const item of gameState.itemsOnTrack) {
                if (item.collected) continue;

                const dx  = activeKart.x - item.x;
                const dy  = activeKart.y - item.y;
                const dist = Math.hypot(dx, dy);

                if (dist < 40 && item.type === "shell") {
                    gameState.itemsOnTrack = gameState.itemsOnTrack.filter(i => i !== item);
                    activeKart.item = "blueShell";
                }
            }
        }
    }
}

/* ========================================
   GAME LOOP
   ======================================== */
function gameLoop() {
    const canvas = document.getElementById("game-canvas");
    const ctx = canvas.getContext("2d");

    // Clear canvas
    ctx.clearRect(0, 0, CANVAS_W, CANVAS_H);

    // Draw track again (simple line-based circuit)
    ctx.beginPath();
    ctx.moveTo(CANVAS_W/2 - TRACK_W, CANVAS_H/2 - TRACK_H/2);
    for (let i = CANVAS_W/2; i < CANVAS_W + TURN_RADIUS; i += 8) {
        const x = Math.cos(i * 0.02) * 16;
        const y = Math.sin(i * 0.02) * 16;
        ctx.lineTo(x, y);
    }

    // Player karts
    for (let i = 0; i < gameState.karts.length; i++) {
        const kart = gameState.karts[i];
        if (!kart.finished && keys["ArrowLeft"] && kart.vx > 0) kart.vx -= 1;
    }

    /* AI Karts */
    for (let j of gameState.karts) {
        if (!j.finished) {
            j.vx += Math.random() * 3;
            j.vy += Math.random() * 3;
            j.x += j.vx;
