    { id: 1, name: "Mario", color: '#ff0000', x: 400, y: 300, angle: 0, speed: 2, item: 'none' },
    { id: 2, name: "Luigi", color: '#00ff00', x: 400, y: 310, angle: Math.PI / 4, speed: 2, item: 'none' },
    { id: 3, name: "Wario", color: '#0000ff', x: 400, y: 290, angle: -Math.PI / 4, speed: 2, item: 'none' }
];

// Track Definition (Simple Oval)
const track = {
    centerX: CANVAS_WIDTH / 2,
    centerY: CANVAS_HEIGHT / 2,
    radiusX: 350,
    radiusY: 200
};

