    window.addEventListener('keyup', (e) => { keys[e.key] = false; });

    players.forEach(p => {
        if (winner && p.id !== winner.id) return; // Stop losers

        // Movement Logic
        let moveX = 0;
        let moveY = 0;

        if (keys['ArrowUp']) moveY -= 2;
        if (keys['ArrowDown']) moveY += 2;
        if (keys['ArrowLeft']) moveX -= 2;
        if (keys['ArrowRight']) moveX += 2;

        // Calculate new position
        p.x += moveX * p.speed;
        p.y += moveY * p.speed;

        // Track Boundaries (Bounce off walls)
        const dx = p.x - track.centerX;
        const dy = p.y - track.centerY;

        // Ellipse equation check: (x/a)^2 + (y/b)^2 <= 1
        if ((dx / track.radiusX) ** 2 + (dy / track.radiusY) ** 2 > 0.95) {
            // Push player back inside
            p.x -= moveX; 
            p.y -= moveY;
            p.speed *= 0.8; // Penalty for hitting wall
        }

        // Mushroom Boost Logic
        if (p.item === 'mushroom') {
            p.speed = 6;
            p.item = 'none';
        }

        // Lap Counting (Simple distance check)
        const distFromCenter = Math.sqrt(dx*dx + dy*dy);
        if (distFromCenter < 50 && frameCount % 100 === 0) {
             // Simplified lap logic: just counting frames for demo
        }

        // Check collision between players
        players.forEach(other => {
            if (p.id !== other.id) {
                const dist = Math.hypot(p.x - other.x, p.y - other.y);
                if (dist < 20) {
                    // Bounce off each other
                    p.x -= moveX;
                    p.y -= moveY;
                }
            }
        });

        // Win Condition Check (Simple: Reach specific coordinates or lap count logic)
        // For this demo, let's say reaching the right side of the track 3 times wins.
        if (p.x > CANVAS_WIDTH - 50 && p.y < CANVAS_HEIGHT / 2 + 50) {
            p.laps++;
            if (p.laps >= 3 && !winner) {
                winner = p.id;
                raceActive = false;
                document.getElementById('pos-display').innerText = "Winner: " + p.name;
            }
        }
    });

    frameCount++;
}

function draw() {
