```javascript
/* Game Configuration */
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// Game State
let playerX = 0;
let playerY = 300; // Center of screen
let speed = 0;
let direction = 'right';
let isGameOver = false;

// Objects
const player = {
    x: 50,
    y: 300,
    width: 40,
    height: 20,
    color: '#FF0000', // Mario Red
    hasItem: false
};

const obstacles = [
    { x: 400, y: 300, type: 'pipe', active: true },
    { x: 700, y: 300, type: 'pipe', active: true }
];

// Input Handling
document.addEventListener('keydown', (e) => {
    if (isGameOver) return;

    switch (e.key) {
        case 'ArrowRight':
            speed = 5;
            direction = 'right';
            break;
        case 'ArrowLeft':
            speed = -5;
            direction = 'left';
            break;
        case 'ArrowUp':
            if (!player.hasItem) {
                player.hasItem = true;
                // Visual feedback: Item collected
                ctx.fillStyle = '#FFFFFF'; 
                ctx.fillRect(0, 0, canvas.width, canvas.height); // Flash screen
            }
            break;
    }
});

document.addEventListener('keyup', (e) => {
    if (e.key.startsWith('Arrow')) {
        speed = 0;
    }
});

// Game Loop
function update() {
    // Move Player
    player.x += speed;

    // Boundary Checks
    if (player.x < 0) {
        player.x = 0;
        speed = 0;
    }

    // Win Condition
    if (player.x > canvas.width - player.width) {
        isGameOver = true;
        alert('You Won!');
        return;
    }

    // Collision Detection
    obstacles.forEach(obs => {
        if (obs.active && 
            Math.abs(player.x - obs.x) < 20 && 
            Math.abs(player.y - obs.y) < 20) {

            isGameOver = true;
            alert('CRASH! Game Over.');
        }
    });

    render();
    requestAnimationFrame(update);
}

// Render Function
function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw Background (Sky)
    ctx.fillStyle = '#87CEFF';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw Ground (Bottom Half)
    ctx.fillStyle = '#2E7D32';
    ctx.fillRect(0, 300, canvas.width, 150);

    // Draw Road (Center Strip)
    ctx.fillStyle = '#666666';
    ctx.fillRect(0, 250, canvas.width, 100);

    // Draw Player (Mario Kart Style Box)
    ctx.save();
    ctx.translate(player.x, player.y);

    // Body
    ctx.fillStyle = player.color;
    ctx.fillRect(-player.width/2, -player.height/2, player.width, player.height);

    // Steering Wheel
    ctx.fillStyle = '#000000';
    ctx.beginPath();
    ctx.arc(0, 0, 15, 0, Math.PI * 2);
    ctx.fill();

    // Item (if collected)
    if (player.hasItem) {
        ctx.fillStyle = '#FF00FF'; // Purple Star
        ctx.fillRect(-10, -30, 20, 10);
    }

    ctx.restore();

    // Draw Obstacles (Pipes)
    obstacles.forEach(obs => {
        if (obs.active) {
            ctx.save();
            ctx.translate(obs.x, obs.y);

            // Pipe Body
            ctx.fillStyle = '#FF0000';
            ctx.beginPath();
            ctx.arc(0, 0, 25, 0, Math.PI * 2);
            ctx.fill();

            // Pipe Hole (Black)
            ctx.fillStyle = '#000000';
            ctx.beginPath();
            ctx.arc(0, 0, 10, 0, Math.PI * 2);
            ctx.fill();

            ctx.restore();
        }
    });
}

// Start Game
update();
```

