```javascript
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// Game State
const gameState = {
    players: [],
    particles: [], // For explosions/items
    time: 0,
    width: canvas.width,
    height: canvas.height
};

// Player Configuration
class Player {
    constructor(name, color) {
        this.name = name;
        this.color = color;
        this.x = 50; // Starting position
        this.y = 300; // Vertical center
        this.speed = 2;
        this.maxSpeed = 10;
        this.boostTimer = 0;
    }
}

// Initialize Players
gameState.players.push(new Player('Mario', '#ff0000'));
gameState.players.push(new Player('Luigi', '#0000ff'));
gameState.players.push(new Player('Wario', '#ffff00'));

// Game Loop
function gameLoop() {
    // Clear screen
    ctx.clearRect(0, 0, gameState.width, gameState.height);

    // Draw Track Background
    drawTrack();

    // Update & Draw Players
    gameState.players.forEach(player => {
        updatePhysics(player);
        drawPlayer(player);
    });

    // Update Particles (Explosions)
    updateParticles();

    gameState.time++;
    requestAnimationFrame(gameLoop);
}

function drawTrack() {
    // Draw grass
    ctx.fillStyle = '#00ff00'; 
    ctx.fillRect(0, 0, gameState.width, gameState.height);

    // Draw road
    ctx.fillStyle = '#cccccc';
    ctx.fillRect(0, 250, gameState.width, 100);

    // Draw checkered start line
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 250, 50, 100);
}

function updatePhysics(player) {
    // Basic movement logic
    if (player.boostTimer > 0) {
        player.speed += 0.1; // Accelerate
    } else {
        player.speed *= 0.99; // Friction
    }

    // Cap speed
    if (player.speed > player.maxSpeed) player.speed = player.maxSpeed;

    // Move right
    player.x += player.speed;

    // Loop around track (wrap around)
    if (player.x > gameState.width) {
        player.x = 0;
    }
}

function drawPlayer(player) {
    ctx.fillStyle = player.color;
    ctx.fillRect(player.x, player.y - 20, 40, 40); // Draw kart body

    // Add wheels (simple visual)
    ctx.fillStyle = '#333333';
    ctx.fillRect(player.x + 5, player.y - 10, 10, 10); // Front wheel
    ctx.fillRect(player.x + 25, player.y - 10, 10, 10); // Back wheel
}

function updateParticles() {
    gameState.particles.forEach((p, index) => {
        p.x += p.vx;
        p.y += p.vy;
        p.life--;

        if (p.life <= 0) {
            gameState.particles.splice(index, 1);
        } else {
            ctx.fillStyle = '#ff8800'; // Fire color
            ctx.fillRect(p.x, p.y, 5, 5);
        }
    });
}

// Input Handling
document.addEventListener('keydown', (e) => {
    const activePlayer = gameState.players[0]; // Simple: Player 1 controls

    if (e.key === 'ArrowRight') {
        activePlayer.boostTimer = 60; // Boost for 1 second
    }
});

// Start Game
gameLoop();
